"""Subscription registration and querying backed by a SQLite ledger."""

from __future__ import annotations

import json
import os
import re
import sqlite3
import sys
from datetime import date, datetime, timedelta, timezone
from pathlib import Path


def _default_db_path() -> Path:
    override = os.environ.get("BILLING_LEDGER_DB")
    return Path(override) if override else Path(__file__).resolve().parents[1] / "ledger.db"


DB_PATH = _default_db_path()

_DATE_FORMAT = re.compile(r"^\d{4}-\d{2}-\d{2}$")

_SCHEMA = """
CREATE TABLE IF NOT EXISTS subscriptions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id TEXT NOT NULL,
    plan TEXT NOT NULL,
    price_cents INTEGER NOT NULL,
    start_date TEXT NOT NULL,
    trial_days INTEGER NOT NULL,
    status TEXT NOT NULL,
    trial_end_date TEXT,
    trial_to_active_date TEXT,
    UNIQUE (customer_id, plan)
)
"""

# Columns added after the original schema; values are backfilled for old rows.
_ADDED_COLUMNS = ("trial_end_date", "trial_to_active_date")


def _connect() -> sqlite3.Connection:
    connection = sqlite3.connect(DB_PATH)
    connection.execute(_SCHEMA)
    existing = {row[1] for row in connection.execute("PRAGMA table_info(subscriptions)")}
    for column in _ADDED_COLUMNS:
        if column not in existing:
            connection.execute(f"ALTER TABLE subscriptions ADD COLUMN {column} TEXT")
    if "trial_to_active_date" not in existing:
        # Rows created before trial dates were tracked: trial_days=0 means the
        # subscription was active from start_date; positive trial_days means a
        # trial interval of [start_date, start_date+trial_days-1].
        connection.execute(
            "UPDATE subscriptions SET trial_to_active_date ="
            " date(start_date, '+' || trial_days || ' days')"
            " WHERE trial_to_active_date IS NULL"
        )
    if "trial_end_date" not in existing:
        connection.execute(
            "UPDATE subscriptions SET trial_end_date ="
            " date(start_date, '+' || (trial_days - 1) || ' days')"
            " WHERE trial_days > 0 AND trial_end_date IS NULL"
        )
    connection.commit()
    return connection


def _fail(message: str) -> int:
    print(f"billing-ledger: error: {message}", file=sys.stderr)
    return 2


def _parse_start_date(raw: str) -> date | None:
    if not _DATE_FORMAT.match(raw):
        return None
    try:
        return datetime.strptime(raw, "%Y-%m-%d").date()
    except ValueError:
        return None


def _record(row: sqlite3.Row | tuple) -> dict:
    return {
        "id": row[0],
        "customer_id": row[1],
        "plan": row[2],
        "price_cents": row[3],
        "start_date": row[4],
        "trial_days": row[5],
        "status": row[6],
    }


def create(
    customer_id: str,
    plan: str,
    price_cents: int,
    start_date: str,
    trial_days: int | None = None,
    trial_end_date: str | None = None,
) -> int:
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")
    if price_cents < 0:
        return _fail("--price-cents must be a non-negative integer")
    if trial_days is not None and trial_days < 0:
        return _fail("--trial-days must be a non-negative integer")
    if trial_days is not None and trial_end_date is not None:
        return _fail("--trial-days and --trial-end-date are mutually exclusive")
    parsed_date = _parse_start_date(start_date)
    if parsed_date is None:
        return _fail(f"--start-date is not a valid YYYY-MM-DD date: {start_date}")
    today = datetime.now(timezone.utc).date()
    if parsed_date > today:
        return _fail(f"--start-date must not be later than today (UTC): {start_date}")

    if trial_end_date is not None:
        parsed_end = _parse_start_date(trial_end_date)
        if parsed_end is None:
            return _fail(
                f"--trial-end-date is not a valid YYYY-MM-DD date: {trial_end_date}"
            )
        if parsed_end < parsed_date:
            return _fail(
                "--trial-end-date must not be earlier than --start-date: "
                f"{trial_end_date} < {start_date}"
            )
        if parsed_end < today:
            return _fail(
                "--trial-end-date must not be earlier than today (UTC): "
                f"{trial_end_date}"
            )
        computed_trial_days = (parsed_end - parsed_date).days + 1
        trial_to_active_date = (parsed_end + timedelta(days=1)).isoformat()
        status = "trial"
    elif trial_days:
        computed_trial_days = trial_days
        trial_end_date = (parsed_date + timedelta(days=trial_days - 1)).isoformat()
        trial_to_active_date = (parsed_date + timedelta(days=trial_days)).isoformat()
        status = "trial"
    else:
        computed_trial_days = 0
        trial_end_date = None
        trial_to_active_date = start_date
        status = "active"

    connection = _connect()
    try:
        cursor = connection.execute(
            "INSERT INTO subscriptions (customer_id, plan, price_cents, start_date,"
            " trial_days, status, trial_end_date, trial_to_active_date)"
            " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (
                customer_id,
                plan,
                price_cents,
                start_date,
                computed_trial_days,
                status,
                trial_end_date,
                trial_to_active_date,
            ),
        )
        connection.commit()
        subscription_id = cursor.lastrowid
    except sqlite3.IntegrityError:
        connection.rollback()
        print(
            f"billing-ledger: duplicate subscription for customer_id={customer_id} plan={plan}",
            file=sys.stderr,
        )
        return 3
    finally:
        connection.close()

    record = {
        "id": subscription_id,
        "customer_id": customer_id,
        "plan": plan,
        "price_cents": price_cents,
        "start_date": start_date,
        "trial_days": computed_trial_days,
        "status": status,
    }
    print(json.dumps(record, ensure_ascii=False, separators=(",", ":")))
    return 0


def list_all() -> int:
    records = []
    if DB_PATH.exists():
        connection = _connect()
        try:
            rows = connection.execute(
                "SELECT id, customer_id, plan, price_cents, start_date, trial_days, status"
                " FROM subscriptions ORDER BY start_date ASC, id DESC"
            ).fetchall()
        finally:
            connection.close()
        records = [_record(row) for row in rows]
    print(json.dumps(records, ensure_ascii=False, separators=(",", ":")))
    return 0


def _trial_view(row: tuple) -> dict:
    return {
        "customer_id": row[0],
        "plan": row[1],
        "start_date": row[2],
        "trial_days": int(row[3]),
        "trial_end_date": row[4],
        "trial_to_active_date": row[5],
        "status": row[6],
    }


def get(customer_id: str, plan: str) -> int:
    """Print the trial information of one subscription as one compact JSON line."""
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    connection = _connect()
    try:
        row = connection.execute(
            "SELECT customer_id, plan, start_date, trial_days, trial_end_date,"
            " trial_to_active_date, status FROM subscriptions"
            " WHERE customer_id = ? AND plan = ?",
            (customer_id, plan),
        ).fetchone()
    finally:
        connection.close()

    if row is None:
        print(
            f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
            file=sys.stderr,
        )
        return 4

    print(json.dumps(_trial_view(row), ensure_ascii=False, separators=(",", ":")))
    return 0


def activate(customer_id: str, plan: str, as_of: str | None = None) -> int:
    """Convert a trial subscription to active status.

    The conversion takes effect on ``as_of`` (defaults to today UTC); it is
    rejected while ``as_of`` is earlier than the persisted conversion date.
    """
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    if as_of is None:
        parsed_as_of = datetime.now(timezone.utc).date()
        as_of = parsed_as_of.isoformat()
    else:
        parsed_as_of = _parse_start_date(as_of)
        if parsed_as_of is None:
            return _fail(f"--as-of is not a valid YYYY-MM-DD date: {as_of}")

    connection = _connect()
    try:
        row = connection.execute(
            "SELECT trial_to_active_date FROM subscriptions"
            " WHERE customer_id = ? AND plan = ?",
            (customer_id, plan),
        ).fetchone()
        if row is None:
            print(
                f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
                file=sys.stderr,
            )
            return 4
        conversion_date = _parse_start_date(str(row[0]))
        if parsed_as_of < conversion_date:
            return _fail(
                f"--as-of must not be earlier than trial_to_active_date {row[0]}: {as_of}"
            )
        connection.execute(
            "UPDATE subscriptions SET status = 'active'"
            " WHERE customer_id = ? AND plan = ?",
            (customer_id, plan),
        )
        connection.commit()
    finally:
        connection.close()

    result = {
        "customer_id": customer_id,
        "plan": plan,
        "status": "active",
        "activated_on": as_of,
    }
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
    return 0

"""Usage recording, per-record querying and daily summarisation.

Records live in the same SQLite ledger as subscriptions; record ids are
globally unique, monotonically allocated by SQLite AUTOINCREMENT and stable
across processes.
"""

from __future__ import annotations

import json
import sqlite3
import sys
from datetime import date, datetime, timedelta, timezone

from .subscriptions import _connect, _parse_start_date

_SCHEMA = """
CREATE TABLE IF NOT EXISTS usage_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    subscription_id INTEGER NOT NULL,
    usage_date TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    FOREIGN KEY (subscription_id) REFERENCES subscriptions (id)
)
"""


def _fail(message: str) -> int:
    print(f"billing-ledger: error: {message}", file=sys.stderr)
    return 2


def _usage_connection() -> sqlite3.Connection:
    # _connect already creates the subscriptions table; add the usage table in
    # the same database so both kinds of data share one file.
    connection = _connect()
    connection.execute(_SCHEMA)
    return connection


def _find_subscription(
    connection: sqlite3.Connection, customer_id: str, plan: str
) -> tuple[int, str] | None:
    row = connection.execute(
        "SELECT id, start_date FROM subscriptions WHERE customer_id = ? AND plan = ?",
        (customer_id, plan),
    ).fetchone()
    if row is None:
        return None
    return int(row[0]), str(row[1])


def _parse_date(raw: str) -> date | None:
    return _parse_start_date(raw)


def record(customer_id: str, plan: str, entries: list[tuple[str, int]]) -> int:
    """Record one or more usage entries in a single atomic submission.

    ``entries`` holds ``(usage_date, quantity)`` pairs in command-line order.
    Several entries for the same subscription on the same date are allowed
    across separate submissions (they add up in the summary), but duplicate
    dates within one submission reject the whole batch.
    """
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    parsed_entries: list[tuple[str, date, int]] = []
    today = datetime.now(timezone.utc).date()
    for usage_date, quantity in entries:
        if quantity < 0:
            return _fail("--quantity must be a non-negative integer")
        parsed_date = _parse_date(usage_date)
        if parsed_date is None:
            return _fail(f"--usage-date is not a valid YYYY-MM-DD date: {usage_date}")
        if parsed_date > today:
            return _fail(f"--usage-date must not be later than today (UTC): {usage_date}")
        parsed_entries.append((usage_date, parsed_date, quantity))

    connection = _usage_connection()
    try:
        found = _find_subscription(connection, customer_id, plan)
        if found is None:
            print(
                f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
                file=sys.stderr,
            )
            return 4
        subscription_id, raw_start_date = found
        start_date = _parse_date(raw_start_date)
        for usage_date, parsed_date, _ in parsed_entries:
            if parsed_date < start_date:
                return _fail(
                    f"--usage-date must not be earlier than subscription start_date "
                    f"{raw_start_date}: {usage_date}"
                )

        seen_dates: set[str] = set()
        for usage_date, _, _ in parsed_entries:
            if usage_date in seen_dates:
                print(
                    "billing-ledger: duplicate usage entries in the same submission for "
                    f"customer_id={customer_id} plan={plan} usage_date={usage_date}",
                    file=sys.stderr,
                )
                return 3
            seen_dates.add(usage_date)

        records: list[dict[str, object]] = []
        try:
            for usage_date, _, quantity in parsed_entries:
                cursor = connection.execute(
                    "INSERT INTO usage_records (subscription_id, usage_date, quantity)"
                    " VALUES (?, ?, ?)",
                    (subscription_id, usage_date, quantity),
                )
                records.append(
                    {
                        "id": cursor.lastrowid,
                        "customer_id": customer_id,
                        "plan": plan,
                        "usage_date": usage_date,
                        "quantity": quantity,
                    }
                )
            connection.commit()
        except Exception:
            connection.rollback()
            raise
    finally:
        connection.close()

    for item in records:
        print(json.dumps(item, ensure_ascii=False, separators=(",", ":")))
    return 0


def list_records(customer_id: str, plan: str) -> int:
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    connection = _usage_connection()
    try:
        found = _find_subscription(connection, customer_id, plan)
        if found is None:
            print(
                f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
                file=sys.stderr,
            )
            return 4
        subscription_id, _ = found
        rows = connection.execute(
            "SELECT id, usage_date, quantity FROM usage_records"
            " WHERE subscription_id = ? ORDER BY id ASC",
            (subscription_id,),
        ).fetchall()
    finally:
        connection.close()

    records = [
        {"id": int(row[0]), "usage_date": row[1], "quantity": int(row[2])} for row in rows
    ]
    print(json.dumps(records, ensure_ascii=False, separators=(",", ":")))
    return 0


def summary(
    customer_id: str,
    plan: str,
    start_date: str | None = None,
    end_date: str | None = None,
) -> int:
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    parsed_start = None
    parsed_end = None
    if start_date is not None:
        parsed_start = _parse_date(start_date)
        if parsed_start is None:
            return _fail(f"--start-date is not a valid YYYY-MM-DD date: {start_date}")
    if end_date is not None:
        parsed_end = _parse_date(end_date)
        if parsed_end is None:
            return _fail(f"--end-date is not a valid YYYY-MM-DD date: {end_date}")
    if parsed_start is not None and parsed_end is not None and parsed_start > parsed_end:
        return _fail(
            f"--start-date must not be later than --end-date: {start_date} > {end_date}"
        )

    connection = _usage_connection()
    try:
        found = _find_subscription(connection, customer_id, plan)
        if found is None:
            print(
                f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
                file=sys.stderr,
            )
            return 4
        subscription_id, _ = found

        clauses = ["subscription_id = ?"]
        parameters: list[object] = [subscription_id]
        if parsed_start is not None:
            clauses.append("usage_date >= ?")
            parameters.append(start_date)
        if parsed_end is not None:
            clauses.append("usage_date <= ?")
            parameters.append(end_date)
        rows = connection.execute(
            "SELECT usage_date, SUM(quantity) FROM usage_records"
            f" WHERE {' AND '.join(clauses)}"
            " GROUP BY usage_date ORDER BY usage_date ASC",
            parameters,
        ).fetchall()
    finally:
        connection.close()

    totals = [{"usage_date": row[0], "total": int(row[1])} for row in rows]
    print(json.dumps(totals, ensure_ascii=False, separators=(",", ":")))
    return 0


def reconcile(customer_id: str, plan: str, start_date: str, end_date: str) -> int:
    """Build the per-day usage reconciliation detail for one billing cycle.

    Read-only: every date in the inclusive ``[start_date, end_date]`` range
    appears exactly once, flagged ``missing`` when no usage was recorded.
    """
    if not customer_id:
        return _fail("--customer-id must not be empty")
    if not plan:
        return _fail("--plan must not be empty")

    parsed_start = _parse_date(start_date)
    if parsed_start is None:
        return _fail(f"--start-date is not a valid YYYY-MM-DD date: {start_date}")
    parsed_end = _parse_date(end_date)
    if parsed_end is None:
        return _fail(f"--end-date is not a valid YYYY-MM-DD date: {end_date}")
    if parsed_start > parsed_end:
        return _fail(
            f"--start-date must not be later than --end-date: {start_date} > {end_date}"
        )

    connection = _usage_connection()
    try:
        found = _find_subscription(connection, customer_id, plan)
        if found is None:
            print(
                f"billing-ledger: no subscription found for customer_id={customer_id} plan={plan}",
                file=sys.stderr,
            )
            return 4
        subscription_id, _ = found
        rows = connection.execute(
            "SELECT usage_date, SUM(quantity) FROM usage_records"
            " WHERE subscription_id = ? AND usage_date >= ? AND usage_date <= ?"
            " GROUP BY usage_date",
            (subscription_id, start_date, end_date),
        ).fetchall()
    finally:
        connection.close()

    totals_by_date = {row[0]: int(row[1]) for row in rows}
    days: list[dict[str, object]] = []
    cycle_total = 0
    present_days = 0
    current = parsed_start
    while current <= parsed_end:
        usage_date = current.isoformat()
        total = totals_by_date.get(usage_date, 0)
        missing = usage_date not in totals_by_date
        if not missing:
            present_days += 1
        cycle_total += total
        days.append({"usage_date": usage_date, "total": total, "missing": missing})
        current += timedelta(days=1)

    detail = {
        "subscription_id": subscription_id,
        "period_start": start_date,
        "period_end": end_date,
        "days": days,
        "cycle_total": cycle_total,
        "coverage": {"present_days": present_days, "missing_days": len(days) - present_days},
    }
    print(json.dumps(detail, ensure_ascii=False, separators=(",", ":")))
    return 0

